🛠️ Yardımcı Fonksiyonlar
# Akıllı Veri Okuma Motoru (Excel veya CSV'yi otomatik tespit eder ve okur)
oku_veri &lt;- function(adaylar, skip = 0, col_names = TRUE) {
  # Dosya listesini oluştur
  olasi_yollar &lt;- unlist(map(adaylar, ~ c(file.path("data", .x), .x)))

  # Sistemdeki tüm dosyaları listele ve kısmi isim eşleştirmesi yap (CSV yedekleri için)
  butun_dosyalar &lt;- list.files(recursive = TRUE)
  bulunan_dosya &lt;- NA_character_

  for (aday in adaylar) {
    base_clean &lt;- str_to_lower(tools::file_path_sans_ext(aday))
    eslesenler &lt;- butun_dosyalar[str_detect(str_to_lower(butun_dosyalar), base_clean)]
    if (length(eslesenler) &gt; 0) {
      bulunan_dosya &lt;- eslesenler[1]
      break
    }
  }

  # Kısmi eşleşme olmazsa tam yolları dene
  if (is.na(bulunan_dosya)) {
    mevcut_yollar &lt;- olasi_yollar[file.exists(olasi_yollar)]
    if (length(mevcut_yollar) &gt; 0) {
      bulunan_dosya &lt;- mevcut_yollar[1]
    }
  }

  if (is.na(bulunan_dosya)) {
    stop(paste0("Dosya bulunamadı. Aranan adaylar: ", paste(adaylar, collapse = ", ")))
  }

  uzanti &lt;- str_to_lower(tools::file_ext(bulunan_dosya))

  if (uzanti %in% c("xlsx", "xls")) {
    return(read_excel(bulunan_dosya, skip = skip, col_names = col_names))
  } else {
    # CSV için ayıraç tespiti (virgül vs noktalı virgül)
    veri &lt;- tryCatch({
      read_csv(bulunan_dosya, skip = skip, col_names = col_names, show_col_types = FALSE)
    }, error = function(e) {
      read_csv2(bulunan_dosya, skip = skip, col_names = col_names, show_col_types = FALSE)
    })
    return(veri)
  }
}

oku_veri_opsiyonel &lt;- function(adaylar, skip = 0, col_names = TRUE) {
  tryCatch({
    oku_veri(adaylar, skip = skip, col_names = col_names)
  }, error = function(e) {
    return(tibble())
  })
}

hacim_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "\\s", "")
  x &lt;- str_replace_all(x, "\\.", "")
  x &lt;- str_replace_all(x, ",", ".")
  as.numeric(x)
}

yuzde_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "%", "")
  x &lt;- str_replace_all(x, "\\s", "")

  has_comma &lt;- str_detect(x, ",")
  x_clean &lt;- x
  if (any(has_comma, na.rm = TRUE)) {
    x_clean &lt;- str_replace_all(x_clean, "\\.", "")
    x_clean &lt;- str_replace_all(x_clean, ",", ".")
  }
  as.numeric(x_clean)
}

ay_sirasi_buyuk &lt;- c(
  "OCAK", "ŞUBAT", "MART", "NİSAN", "MAYIS", "HAZİRAN",
  "TEMMUZ", "AĞUSTOS", "EYLÜL", "EKİM", "KASIM", "ARALIK"
)

ay_sirasi &lt;- c(
  "Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran",
  "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"
)

ay_tablosu &lt;- tibble(
  ay_no = 1:12,
  ay = factor(ay_sirasi, levels = ay_sirasi, ordered = TRUE),
  ay_buyuk = ay_sirasi_buyuk
)

💧 Aylık Barajlara Gelen Su Miktarı
baraj_raw &lt;- oku_veri(
  c(
    "baraj_su.xlsx",
    "Aylik_Baraj_Su_Miktari.xlsx",
    "Aylık_Baraj_Su_Miktari.xlsx",
    "Aylik Baraj Su Miktari.xlsx"
  ),
  skip = 1
)

names(baraj_raw) &lt;- names(baraj_raw) |&gt;
  str_squish() |&gt;
  str_to_upper(locale = "tr")

yil_col &lt;- names(baraj_raw)[str_detect(names(baraj_raw), "YIL")][1]

baraj_raw &lt;- baraj_raw |&gt;
  rename(YILLAR = all_of(yil_col))

eksik_aylar &lt;- setdiff(ay_sirasi_buyuk, names(baraj_raw))

if (length(eksik_aylar) &gt; 0) {
  stop(paste("Baraj dosyasında eksik ay sütunları var:", paste(eksik_aylar, collapse = ", ")))
}

baraj_long &lt;- baraj_raw |&gt;
  mutate(YILLAR = as.integer(YILLAR)) |&gt;
  select(YILLAR, all_of(ay_sirasi_buyuk), any_of("TOPLAM")) |&gt;
  mutate(across(all_of(ay_sirasi_buyuk), hacim_sayi)) |&gt;
  pivot_longer(
    cols = all_of(ay_sirasi_buyuk),
    names_to = "ay_buyuk",
    values_to = "gelen_su_m3"
  ) |&gt;
  left_join(ay_tablosu, by = "ay_buyuk") |&gt;
  transmute(
    yil = YILLAR,
    ay_no,
    ay,
    tarih = as.Date(paste(yil, ay_no, "01", sep = "-")),
    gelen_su_m3,
    gelen_su_milyon_m3 = gelen_su_m3 / 1e6
  ) |&gt;
  filter(!is.na(yil), !is.na(gelen_su_m3)) |&gt;
  arrange(yil, ay_no)

baraj_long |&gt;
  head(12) |&gt;
  kable(digits = 2, caption = "Barajlara gelen aylık su miktarı verisinin ilk satırları") |&gt;
  kable_styling(bootstrap_options = c("striped", "hover", "condensed"), full_width = FALSE)

🌧️ Ankara Yağış Verisi
yagis_raw &lt;- oku_veri(
  c(
    "yagis.xlsx",
    "Ankara Yağış Verileri (2023-2026).xlsx",
    "Ankara Yağış Verileri (2023-2026)(1).xlsx",
    "Ankara Yagis Verileri (2023-2026).xlsx"
  )
)

names(yagis_raw) &lt;- names(yagis_raw) |&gt;
  str_squish()

tarih_col &lt;- names(yagis_raw)[str_detect(str_to_lower(names(yagis_raw)), "date|time|tarih")][1]
prcp_col &lt;- names(yagis_raw)[str_detect(str_to_lower(names(yagis_raw)), "^prcp|yağış|yagis")][1]
temp_col &lt;- names(yagis_raw)[str_detect(str_to_lower(names(yagis_raw)), "^tavg|temp|sicak|sıcak")][1]

if (is.na(tarih_col)) {
  stop("Yağış dosyasında tarih/time sütunu bulunamadı.")
}

if (is.na(prcp_col)) {
  stop("Yağış dosyasında prcp/yağış sütunu bulunamadı.")
}

yagis_gunluk &lt;- yagis_raw |&gt;
  mutate(
    tarih_saat = .data[[tarih_col]],
    yagis_mm = hacim_sayi(.data[[prcp_col]])
  )

if (!is.na(temp_col)) {
  yagis_gunluk &lt;- yagis_gunluk |&gt;
    mutate(sicaklik = hacim_sayi(.data[[temp_col]]))
} else {
  yagis_gunluk &lt;- yagis_gunluk |&gt;
    mutate(sicaklik = NA_real_)
}

yagis_gunluk &lt;- yagis_gunluk |&gt;
  transmute(
    tarih_saat,
    yagis_mm,
    sicaklik,
    tarih = as.Date(as.POSIXct(tarih_saat, tz = "Europe/Istanbul"))
  ) |&gt;
  group_by(tarih) |&gt;
  summarise(
    gunluk_yagis_mm = sum(yagis_mm, na.rm = TRUE),
    ortalama_sicaklik = mean(sicaklik, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(
    yil = year(tarih),
    ay_no = month(tarih),
    ay = factor(ay_sirasi[ay_no], levels = ay_sirasi, ordered = TRUE)
  )

yagis_aylik &lt;- yagis_gunluk |&gt;
  group_by(yil, ay_no, ay) |&gt;
  summarise(
    aylik_yagis_mm = sum(gunluk_yagis_mm, na.rm = TRUE),
    ortalama_sicaklik = mean(ortalama_sicaklik, na.rm = TRUE),
    gun_sayisi = n(),
    .groups = "drop"
  ) |&gt;
  mutate(
    tarih = as.Date(paste(yil, ay_no, "01", sep = "-"))
  )

yagis_aylik |&gt;
  head(12) |&gt;
  kable(digits = 2, caption = "Aylık toplam yağış verisinin ilk satırları") |&gt;
  kable_styling(bootstrap_options = c("striped", "hover", "condensed"), full_width = FALSE)

📈 Dağıtılan, Çekilen ve Kişi Başı Çekilen Su Verisi
raw_kullanim &lt;- oku_veri_opsiyonel(
  c(
    "dagitilan_cekilen.xls",
    "dagitilan_cekilen.xlsx",
    "DAGITILAN CEKILEN VE KIS BASI CEKILEN.xls",
    "DAGITILAN CEKILEN VE KIS BASI CEKILEN.xlsx",
    "DAGITILAN CEKILEN VE KISI BASI CEKILEN.xls"
  ),
  col_names = FALSE
)

if (nrow(raw_kullanim) &gt; 0) {
  # Kolon isimlendirmelerini sabitleyerek kütüphane uyumsuzluğunu önlüyoruz
  names(raw_kullanim)[1:min(5, ncol(raw_kullanim))] &lt;- paste0("col", 1:min(5, ncol(raw_kullanim)))

  su_kullanim &lt;- raw_kullanim |&gt;
    slice(6:n()) |&gt;
    transmute(
      yil = as.numeric(col2),
      dagitilan_su_m3 = hacim_sayi(col3),
      cekilen_su_bin_m3 = hacim_sayi(col4),
      kisi_basi_litre_gun = hacim_sayi(col5)
    ) |&gt;
    filter(!is.na(yil)) |&gt;
    mutate(
      dagitilan_su_milyon_m3 = dagitilan_su_m3 / 1e6,
      cekilen_su_milyon_m3 = cekilen_su_bin_m3 / 1000
    )
} else {
  su_kullanim &lt;- tibble()
}

if (nrow(su_kullanim) &gt; 0) {
  su_kullanim |&gt;
    head(10) |&gt;
    kable(digits = 2, caption = "Dağıtılan, çekilen ve kişi başı çekilen su verisi") |&gt;
    kable_styling(bootstrap_options = c("striped", "hover", "condensed"), full_width = FALSE)
} else {
  tibble(
    bilgi = "Dağıtılan/çekilen su dosyası bulunamadı. Bu bölüm atlanacaktır."
  ) |&gt;
    kable(caption = "Dosya durumu") |&gt;
    kable_styling(full_width = FALSE)
}

🗺️ Suyun Kaynaklara Göre Dağılımı
raw_kaynak &lt;- oku_veri_opsiyonel(
  c(
    "sular_nereden_geliyor.xls",
    "sular_nereden_geliyor.xlsx",
    "sular nereden geliyor.xls",
    "sular nereden geliyor.xlsx"
  ),
  col_names = FALSE
)

if (nrow(raw_kaynak) &gt; 0) {
  # Kolon isimlendirmelerini sabitleyerek kütüphane uyumsuzluğunu önlüyoruz
  names(raw_kaynak)[1:min(7, ncol(raw_kaynak))] &lt;- paste0("col", 1:min(7, ncol(raw_kaynak)))

  su_kaynak &lt;- raw_kaynak |&gt;
    slice(6:n()) |&gt;
    transmute(
      yil = as.numeric(col2),
      akarsu = hacim_sayi(col3),
      baraj = hacim_sayi(col4),
      golet = hacim_sayi(col5),
      kaynak = hacim_sayi(col6),
      kuyu = hacim_sayi(col7)
    ) |&gt;
    filter(!is.na(yil)) |&gt;
    mutate(across(akarsu:kuyu, ~ replace_na(.x, 0)))

  su_kaynak_long &lt;- su_kaynak |&gt;
    pivot_longer(
      cols = akarsu:kuyu,
      names_to = "kaynak_turu",
      values_to = "su_bin_m3"
    ) |&gt;
    mutate(
      kaynak_turu = str_to_title(kaynak_turu, locale = "tr"),
      su_milyon_m3 = su_bin_m3 / 1000
    )
} else {
  su_kaynak &lt;- tibble()
  su_kaynak_long &lt;- tibble()
}

if (nrow(su_kaynak_long) &gt; 0) {
  su_kaynak_long |&gt;
    head(10) |&gt;
    kable(digits = 2, caption = "Suyun kaynaklara göre dağılımı") |&gt;
    kable_styling(bootstrap_options = c("striped", "hover", "condensed"), full_width = FALSE)
} else {
  tibble(
    bilgi = "Sular nereden geliyor dosyası bulunamadı. Kaynak kompozisyonu bölümü atlanacaktır."
  ) |&gt;
    kable(caption = "Dosya durumu") |&gt;
    kable_styling(full_width = FALSE)
}

🌧️ Yağış ve Barajlara Gelen Su İlişkisi
yagis_baraj &lt;- baraj_long |&gt;
  inner_join(
    yagis_aylik,
    by = c("yil", "ay_no", "ay", "tarih")
  ) |&gt;
  filter(!is.na(gelen_su_m3), !is.na(aylik_yagis_mm))

yagis_baraj |&gt;
  select(yil, ay, aylik_yagis_mm, gelen_su_milyon_m3) |&gt;
  head(12) |&gt;
  kable(digits = 2, caption = "Yağış ve barajlara gelen su birleşik veri seti") |&gt;
  kable_styling(bootstrap_options = c("striped", "hover", "condensed"), full_width = FALSE)
ggplot(yagis_baraj, aes(x = aylik_yagis_mm, y = gelen_su_milyon_m3)) +
  geom_point(size = 2, alpha = 0.8, color = "#2c7fb8") +
  geom_smooth(method = "lm", se = FALSE, color = "#de2d26", linetype = "dashed") +
  labs(
    title = "Aylık Yağış ve Barajlara Gelen Su İlişkisi",
    x = "Aylık Yağış (mm)",
    y = "Barajlara Gelen Su (Milyon m³)"
  ) +
  theme_minimal()
korelasyon_yagis_baraj &lt;- cor(
  yagis_baraj$aylik_yagis_mm,
  yagis_baraj$gelen_su_milyon_m3,
  use = "complete.obs"
)

tibble(
  Gösterge = "Aylık yağış ile barajlara gelen su korelasyonu",
  Korelasyon = korelasyon_yagis_baraj
) |&gt;
  kable(digits = 3) |&gt;
  kable_styling(bootstrap_options = c("striped", "hover"), full_width = FALSE)
Yağış ve barajlara gelen su arasında pozitif bir ilişki beklenmektedir. Ancak bu ilişkinin birebir olması beklenmez. Çünkü yağışın baraja ulaşması havza özelliklerine, kar erimesine, buharlaşmaya, toprak nemine ve yüzey akışına bağlıdır.

🌊 Su Kaynakları Analizi
if (nrow(su_kaynak_long) &gt; 0) {
  ggplot(su_kaynak_long, aes(x = factor(yil), y = su_milyon_m3, fill = kaynak_turu)) +
    geom_col() +
    scale_fill_brewer(palette = "Set2") +
    labs(
      title = "Ankara İçme ve Kullanma Suyunun Kaynaklara Göre Dağılımı",
      x = "Yıl",
      y = "Çekilen Su (Milyon m³)",
      fill = "Kaynak Türü"
    ) +
    theme_minimal()
}
if (nrow(su_kaynak_long) &gt; 0) {
  su_kaynak_pay &lt;- su_kaynak_long |&gt;
    group_by(yil) |&gt;
    mutate(
      pay = su_bin_m3 / sum(su_bin_m3, na.rm = TRUE)
    ) |&gt;
    ungroup()

  ggplot(su_kaynak_pay, aes(x = factor(yil), y = pay, fill = kaynak_turu)) +
    geom_col(position = "fill") +
    scale_y_continuous(labels = percent) +
    scale_fill_brewer(palette = "Set2") +
    labs(
      title = "Su Kaynaklarının Yüzdesel Payı",
      x = "Yıl",
      y = "Pay",
      fill = "Kaynak Türü"
    ) +
    theme_minimal()
}
Kaynak kompozisyonu Ankara’nın su arzında barajların stratejik önemini göstermektedir. Baraj kaynaklı suyun baskın hale gelmesi, yağış rejimi ve baraj doluluklarının su yönetimi açısından daha kritik hale gelmesine neden olmaktadır.

📉 Yağış ve Gelen Su Modeli
model_yagis &lt;- lm(gelen_su_milyon_m3 ~ aylik_yagis_mm, data = yagis_baraj)

tidy(model_yagis) |&gt;
  kable(digits = 4, caption = "Yağış ve barajlara gelen su regresyon modeli katsayıları") |&gt;
  kable_styling(bootstrap_options = c("striped", "hover"), full_width = FALSE)

glance(model_yagis) |&gt;
  select(r.squared, adj.r.squared, sigma, statistic, p.value) |&gt;
  kable(digits = 4, caption = "Yağış modeli uyum ölçütleri") |&gt;
  kable_styling(bootstrap_options = c("striped", "hover"), full_width = FALSE)
Bu model yağış miktarı ile barajlara gelen su miktarı arasındaki doğrusal ilişkiyi incelemek için kurulmuştur. Model nedensellik kanıtı olarak değil, keşifsel ilişki analizi olarak değerlendirilmelidir.

📈 Dağıtılan Su Trend Modeli
if (nrow(su_kullanim) &gt; 0) {
  model_dagitilan &lt;- lm(dagitilan_su_milyon_m3 ~ yil, data = su_kullanim)

  tidy(model_dagitilan) |&gt;
    kable(digits = 4, caption = "Dağıtılan su trend modeli katsayıları") |&gt;
    kable_styling(bootstrap_options = c("striped", "hover"), full_width = FALSE)

  glance(model_dagitilan) |&gt;
    select(r.squared, adj.r.squared, sigma, statistic, p.value) |&gt;
    kable(digits = 4, caption = "Dağıtılan su trend modeli uyum ölçütleri") |&gt;
    kable_styling(bootstrap_options = c("striped", "hover"), full_width = FALSE)
}
if (nrow(su_kullanim) &gt; 0) {
  ggplot(su_kullanim, aes(x = yil, y = dagitilan_su_milyon_m3)) +
    geom_point(size = 3, color = "#54278f") +
    geom_smooth(method = "lm", se = TRUE, color = "#756bb1") +
    labs(
      title = "Dağıtılan Su Miktarı İçin Doğrusal Trend",
      x = "Yıl",
      y = "Dağıtılan Su (Milyon m³)"
    ) +
    theme_minimal()
}
